async () => {
  const first = await connecta.search({ query: "list organizations projects", safety: "readOnly", includeSchemas: "compact" });
  const toolsFound = first.tools || [];
  const projectTool = toolsFound.find(t => /project/i.test(t.address + " " + (t.description || "")) && /list|search|get/i.test(t.address + " " + (t.description || "")));
  const orgTool = toolsFound.find(t => /organi[sz]ation/i.test(t.address + " " + (t.description || "")) && /list/i.test(t.address + " " + (t.description || "")));
  if (!projectTool || !orgTool) {
    const second = await connecta.search({ query: "find project list organizations", safety: "readOnly", includeSchemas: "compact" });
    for (const x of second.tools || []) if (!toolsFound.some(y => y.address === x.address)) toolsFound.push(x);
  }
  const pTool = toolsFound.find(t => /project/i.test(t.address + " " + (t.description || "")) && (t.requiredInputKeys || []).every(k => /query|search|name|project/i.test(k)));
  const oTool = toolsFound.find(t => /organi[sz]ation/i.test(t.address + " " + (t.description || "")) && /list/i.test(t.address + " " + (t.description || "")));
  if (!pTool || !oTool) throw new Error("Required project or organization tool not found");
  const pKeys = pTool.requiredInputKeys || [];
  const pArgs = {};
  for (const k of pKeys) {
    if (/query|search|name|project/i.test(k)) pArgs[k] = "mxp_eval_42";
    else throw new Error("Unsupported required project key: " + k);
  }
  const projectResult = await connecta.call(pTool.address, pArgs);
  const findProject = (v) => {
    if (!v || typeof v !== "object") return null;
    if (!Array.isArray(v) && Object.values(v).some(x => x === "mxp_eval_42")) return v;
    for (const x of Object.values(v)) {
      if (Array.isArray(x)) { for (const y of x) { const z = findProject(y); if (z) return z; } }
      else if (x && typeof x === "object") { const z = findProject(x); if (z) return z; }
    }
    return null;
  };
  const project = findProject(projectResult) || projectResult;
  const oArgs = {};
  for (const k of (oTool.requiredInputKeys || [])) {
    if (/project.*id|project_id/i.test(k)) oArgs[k] = project.id ?? project.projectId ?? project.project_id;
    else if (/project.*name|project|name/i.test(k)) oArgs[k] = project.name ?? project.slug ?? "mxp_eval_42";
    else throw new Error("Unsupported required organization key: " + k);
    if (oArgs[k] == null) throw new Error("Missing project value for " + k);
  }
  return await connecta.call(oTool.address, oArgs);
}

async () => {
  const s = await connecta.search({ query: "list organizations projects", safety: "readOnly", includeSchemas: "compact", limit: 100 });
  console.log(JSON.stringify((s.tools || []).map(t => ({address:t.address,description:t.description,requiredInputKeys:t.requiredInputKeys,inputKeys:t.inputKeys,outputKeys:t.outputKeys,queryCoverage:t.queryCoverage}))));
  const candidates = (s.tools || []).filter(t => /organi[sz]ation/i.test(t.address + " " + (t.description || "")));
  if (!candidates.length) throw new Error("No organization tool matched");
  const ranked = candidates.sort((a,b) => {
    const score = t => (/list/i.test(t.address)?5:0) + (/project/i.test((t.requiredInputKeys||[]).join(" ")?t.address:"")?0:0) + (/project/i.test((t.requiredInputKeys||[]).join(" "))?4:0) + (/analytics/i.test(t.address+" "+(t.description||""))?2:0);
    return score(b)-score(a);
  });
  for (const tool of ranked) {
    const args = {};
    let compatible = true;
    for (const k of (tool.requiredInputKeys || [])) {
      if (/project.*id|project_id|projectid/i.test(k)) args[k] = "mxp_eval_42";
      else if (/project.*name|project|name|slug|query|search/i.test(k)) args[k] = "mxp_eval_42";
      else compatible = false;
    }
    if (!compatible) continue;
    try { return await connecta.call(tool.address, args); } catch (e) { console.log(tool.address + ": " + e.message); }
  }
  throw new Error("No compatible organization listing call succeeded");
}

